const m = @import("model.zig");
// Broken movement: ignores walls, pickups and the exit.
pub fn can_enter(state: *const m.Runner, x: i32, y: i32) bool {
    _ = state;
    return x >= 0 and y >= 0 and x < m.width and y < m.height;
}
pub fn runner_step(state: *m.Runner, action: u8) void {
    if (state.won) return;
    state.ticks += 1;
    state.moved = false;
    const dx: i32 = if (action == 'd') 1 else if (action == 'a') -1 else 0;
    const dy: i32 = if (action == 's') 1 else if (action == 'w') -1 else 0;
    if ((dx != 0 or dy != 0) and can_enter(state, state.x + dx, state.y + dy)) {
        state.x += dx;
        state.y += dy;
        state.moved = true;
    }
}

solution.mechanics.zig:
const m = @import("model.zig");
pub fn can_enter(state: *const m.Runner, x: i32, y: i32) bool {
    _ = state;
    return x >= 0 and y >= 0 and x < m.width and y < m.height and m.board[@intCast(y)][@intCast(x)] != '#';
}
pub fn runner_step(state: *m.Runner, action: u8) void {
    if (state.won) return;
    state.ticks += 1;
    state.moved = false;
    const dx: i32 = if (action == 'd') 1 else if (action == 'a') -1 else 0;
    const dy: i32 = if (action == 's') 1 else if (action == 'w') -1 else 0;
    if ((dx == 0 and dy == 0) or !can_enter(state, state.x + dx, state.y + dy)) return;
    state.x += dx;
    state.y += dy;
    state.moved = true;
    if (state.y == 4 and state.x == 3) state.coins |= 1;
    if (state.y == 4 and state.x == 5) state.coins |= 2;
    state.won = state.x == 7 and state.y == 1 and state.coins == 3;
}

