pub const width = 9;
pub const height = 6;
pub const board = [_][]const u8{ "#########", "#P..#..G#", "#.#.#...#", "#.#...#.#", "#..C.C..#", "#########" };
// All state is owned by value; board rows are borrowed immutable literals.
pub const Runner = struct { x: i32 = 1, y: i32 = 1, coins: u32 = 0, won: bool = false, ticks: u32 = 0, moved: bool = false };
pub fn runner_initial() Runner {
    return .{};
}

files.main.zig:
const std = @import("std");
const m = @import("model.zig");
const learner = @import("mechanics.zig");
extern "c" fn printf(format: [*:0]const u8, ...) c_int;
extern "c" fn getchar() c_int;
extern "c" fn putchar(c_int) c_int;
extern "c" fn puts([*:0]const u8) c_int;
extern "c" fn exit(c_int) noreturn;
fn truth(b: bool) [*:0]const u8 {
    return if (b) "true" else "false";
}
fn frame(s: m.Runner, action: u8) void {
    _ = printf("{\"type\":\"frame\",\"tick\":%u,\"action\":\"%c\",\"x\":%d,\"y\":%d,\"coins\":%u,\"won\":%s,\"moved\":%s}\n", @as(c_uint, s.ticks), @as(c_int, action), @as(c_int, s.x), @as(c_int, s.y), @as(c_uint, s.coins), truth(s.won), truth(s.moved));
}
fn draw(s: m.Runner) void {
    _ = puts("\nTile Runner: w/a/s/d + Enter; q quits. @ is you, C is a coin, G is the exit.");
    for (m.board, 0..) |row, y| {
        for (row, 0..) |original, x| {
            var cell = original;
            if (cell == 'P') cell = '.';
            if (y == 4 and x == 3 and s.coins & 1 != 0) cell = '.';
            if (y == 4 and x == 5 and s.coins & 2 != 0) cell = '.';
            if (s.x == x and s.y == y) cell = '@';
            _ = putchar(@as(c_int, cell));
        }
        _ = putchar(10);
    }
    const count = @as(c_uint, @intFromBool(s.coins & 1 != 0)) + @as(c_uint, @intFromBool(s.coins & 2 != 0));
    _ = printf("Coins %u/2 | tick %u | %s\n", count, @as(c_uint, s.ticks), @as([*:0]const u8, if (s.won) "YOU WIN" else if (s.moved) "Moved" else "Wall or wait"));
}
pub fn main(init: std.process.Init) !void {
    const args = try init.minimal.args.toSlice(init.arena.allocator());
    var s = m.runner_initial();
    if (args.len == 3 and std.mem.eql(u8, args[1], "--replay")) {
        _ = puts("{\"type\":\"header\",\"project\":\"tile-runner\",\"version\":1,\"language\":\"zig\"}");
        frame(s, '.');
        for (args[2]) |action| {
            if (s.won) break;
            if (std.mem.indexOfScalar(u8, "wasd.", action) == null) {
                _ = puts("Replay actions must use w/a/s/d/.");
                exit(2);
            }
            learner.runner_step(&s, action);
            frame(s, action);
        }
        return;
    }
    if (args.len != 1) {
        _ = puts("Usage: game [--replay ACTIONS]");
        exit(2);
    }
    draw(s);
    while (!s.won) {
        const input = getchar();
        if (input < 0 or input == 'q') break;
        if (input > 255) continue;
        const action: u8 = @intCast(input);
        if (std.mem.indexOfScalar(u8, "wasd.", action) == null) continue;
        learner.runner_step(&s, action);
        draw(s);
    }
}

files.tests.zig:
const std = @import("std");
const t = std.testing;
const m = @import("model.zig");
const learner = @import("mechanics.zig");
test "walls and bounds reject movement" {
    const s = m.runner_initial();
    try t.expect(!learner.can_enter(&s, 0, 1));
    try t.expect(!learner.can_enter(&s, -1, 1));
    try t.expect(!learner.can_enter(&s, m.width, 1));
}
test "walk to adjacent floor" {
    var s = m.runner_initial();
    learner.runner_step(&s, 'd');
    try t.expect(s.x == 2 and s.y == 1 and s.moved and s.ticks == 1);
}
test "wall blocks the player" {
    var s = m.runner_initial();
    for ("ddd") |a| learner.runner_step(&s, a);
    try t.expect(s.x == 3 and s.y == 1 and !s.moved);
}
test "wait records a native tick without movement" {
    var s = m.runner_initial();
    learner.runner_step(&s, '.');
    try t.expect(s.ticks == 1 and !s.moved and s.x == 1);
}
test "pickups are collected only once" {
    var s = m.runner_initial();
    s.x = 2;
    s.y = 4;
    learner.runner_step(&s, 'd');
    try t.expect(s.coins == 1);
    learner.runner_step(&s, 'a');
    learner.runner_step(&s, 'd');
    try t.expect(s.coins == 1);
}
test "exit requires both coins" {
    var s = m.runner_initial();
    s.x = 7;
    s.y = 2;
    learner.runner_step(&s, 'w');
    try t.expect(!s.won);
}
test "real level has a playable winning route" {
    var s = m.runner_initial();
    for ("sssddddddwww") |a| learner.runner_step(&s, a);
    try t.expect(s.won and s.coins == 3 and s.x == 7 and s.y == 1);
}
test "won state does not move again" {
    var s = m.runner_initial();
    for ("sssddddddwww") |a| learner.runner_step(&s, a);
    const tick = s.ticks;
    learner.runner_step(&s, 's');
    try t.expect(s.won and s.ticks == tick and s.y == 1);
}
